const request = $input.first().json;
const body = request.body ?? request;

if (body.mode !== 'dry_run') {
  throw new Error('Only dry_run mode is accepted.');
}

if (!body.correlation_id || !body.content_variant_id || !body.export_reference) {
  throw new Error('The CWS handoff payload is incomplete.');
}

return [{
  json: {
    ok: true,
    mode: 'dry_run',
    workflow: 'CWS OS — Dry Run Bridge',
    correlation_id: body.correlation_id,
    received: {
      workspace_id: body.workspace_id,
      campaign_id: body.campaign_id,
      campaign_code: body.campaign_code,
      content_variant_id: body.content_variant_id,
      variant_code: body.variant_code,
      locale: body.locale,
      export_version: body.export_version,
      export_reference: body.export_reference
    }
  }
}];
